def test_uploadImage(base_url, auth_headers, sample_payload, pet_id, metadata, expected_status):
    """
    Test `/pet/{petId}/uploadImage` endpoint with valid and invalid cases.
    Covers success and error states.
    """
    url = f"{base_url}/pet/{pet_id}/uploadImage"
    files = {"file": sample_payload["file"]}
    params = {"additionalMetadata": metadata} if metadata else {}

    response = requests.post(url, headers=auth_headers, params=params, files=files)

    assert response.status_code == expected_status

    if response.status_code == 200:
        response_data = response.json()
        assert "code" in response_data
        assert "type" in response_data
        assert "message" in response_data
    elif response.status_code == 404:
        assert "Pet not found" in response.text
    elif response.status_code == 400:
        assert "No file uploaded" in response.text
    else:
        assert response.status_code >= 500  # Unexpected server errors


