def test_boundary_cases_petId(base_url, auth_headers, sample_payload):
    """
    Test `/pet/{petId}/uploadImage` endpoint with edge case petId values.
    """
    edge_cases = [0, 999999999999, -1]  # Boundary values
    url = f"{base_url}/pet/{{pet_id}}/uploadImage"

    for pet_id in edge_cases:
        response = requests.post(url.format(pet_id=pet_id), headers=auth_headers, files=sample_payload["file"])
        if pet_id < 0 or pet_id == 0:
            assert response.status_code == 404
        elif pet_id > 99999999:
            assert response.status_code == 400


